-- Phase 22 synthetic implant education content. Geometry is generated internally by Prostheia.
-- No patient data or proprietary implant library is bundled.

insert into public.practice_modules(id,slug,title_en,title_sr,summary_en,summary_sr,sort_order,status)
values ('b7220000-0000-4000-8000-000000000001','implant_practice','Implant Practice','Implantološka vežba','Advanced synthetic implant restoration workflows in the shared CAD workspace.','Napredni sintetički implantološki restorativni postupci u zajedničkom CAD radnom prostoru.',110,'published')
on conflict(slug) do update set title_en=excluded.title_en,title_sr=excluded.title_sr,summary_en=excluded.summary_en,summary_sr=excluded.summary_sr,sort_order=excluded.sort_order,status='published';

insert into public.practice_lessons(id,module_id,slug,difficulty,title_en,title_sr,summary_en,summary_sr,goal_en,goal_sr,estimated_minutes,case_setup,sort_order,status)
select v.id,m.id,v.slug,'advanced'::public.difficulty_level,v.title_en,v.title_sr,v.summary_en,v.summary_sr,v.goal_en,v.goal_sr,v.minutes,jsonb_build_object('source','implant-case','objectMappings','[]'::jsonb),v.sort_order,'published'
from (values
 ('b7220000-0000-4000-8000-000000000010'::uuid,'scan_body_matching',10,'Scan Body Matching','Uparivanje scan body-ja','Inspect the supplied synthetic scan body and its explicit fixture relationship.','Pregledajte dostavljeni sintetički scan body i njegovu izričitu vezu sa implantatom.','Relate a synthetic scan body to the fixture using stable object identities.','Povežite sintetički scan body sa implantatom pomoću stabilnih identiteta objekata.',7),
 ('b7220000-0000-4000-8000-000000000011'::uuid,'implant_visualization',20,'Implant Fixture and Axis','Implantat i osa','Inspect the generic training fixture, its dimensions and the displayed Implant Axis.','Pregledajte generički vežbovni implantat, njegove dimenzije i prikazanu osu implantata.','Identify the selected synthetic fixture and read its transform-derived axis.','Prepoznajte izabrani sintetički implantat i očitajte osu izvedenu iz transformacije.',7),
 ('b7220000-0000-4000-8000-000000000012'::uuid,'position_and_depth',30,'Position and Depth','Položaj i dubina','Adjust the fixture position and exercise depth in millimetres.','Podesite položaj implantata i dubinu vežbe u milimetrima.','Set a synthetic exercise depth relative to the top plane of the synthetic site block.','Podesite sintetičku dubinu vežbe u odnosu na gornju ravan sintetičkog bloka mesta.',8),
 ('b7220000-0000-4000-8000-000000000013'::uuid,'angulation_and_axis',40,'Angulation and Restorative Axis','Angulacija i restaurativna osa','Compare the implant axis and the exercise restorative reference axis.','Uporedite osu implantata i referentnu restaurativnu osu vežbe.','Read an explicit angle in degrees and treat configured values only as exercise targets.','Očitajte ugao u stepenima i posmatrajte podešene vrednosti samo kao ciljeve vežbe.',8),
 ('b7220000-0000-4000-8000-000000000014'::uuid,'custom_abutment_and_emergence',50,'Custom Abutment and Emergence Profile','Prilagođeni abatment i profil izranjanja','Adjust simplified synthetic abutment and emergence references, then inspect the typed link.','Podesite pojednostavljeni sintetički abatment i referencu profila izranjanja, pa pregledajte tipizovanu vezu.','Use a reversible shared transform on educational reference geometry only.','Koristite reverzibilnu zajedničku transformaciju samo na edukativnoj referentnoj geometriji.',9),
 ('b7220000-0000-4000-8000-000000000015'::uuid,'screw_channel_and_crown',60,'Screw Channel and Crown Integration','Screw channel i povezivanje krunice','Inspect the visual screw-channel reference and crown generated by the shared restorative geometry.','Pregledajte vizuelnu referencu screw channel-a i krunicu generisanu zajedničkom restorativnom geometrijom.','Distinguish a relationship and axis marker from engineered channel geometry or manufacturing validation.','Razlikujte vezu i oznaku ose od projektovane geometrije kanala ili validacije izrade.',9),
 ('b7220000-0000-4000-8000-000000000016'::uuid,'implant_review_capstone',70,'Implant Restoration Review','Završni pregled implantološke nadoknade','Review fixture identity, depth, axis, proximity, synthetic reference geometry and restoration relationships.','Pregledajte identitet implantata, dubinu, osu, blizinu, sintetičku referentnu geometriju i veze nadoknade.','Run shared distance inspection and Design Check against the configured targets for this exercise.','Pokrenite zajedničku analizu rastojanja i Design Check prema podešenim ciljevima ove vežbe.',12)
) v(id,slug,sort_order,title_en,title_sr,summary_en,summary_sr,goal_en,goal_sr,minutes)
join public.practice_modules m on m.slug='implant_practice'
on conflict(slug) do update set module_id=excluded.module_id,difficulty=excluded.difficulty,title_en=excluded.title_en,title_sr=excluded.title_sr,summary_en=excluded.summary_en,summary_sr=excluded.summary_sr,goal_en=excluded.goal_en,goal_sr=excluded.goal_sr,estimated_minutes=excluded.estimated_minutes,case_setup=excluded.case_setup,sort_order=excluded.sort_order,status='published';

create or replace function pg_temp.seed_phase22_step(p_lesson text,p_slug text,p_title_en text,p_title_sr text,p_instructions_en text,p_instructions_sr text,p_theory_en text,p_theory_sr text,p_tools text[],p_targets text[],p_validators jsonb[])
returns void language plpgsql as $$
declare lesson_key uuid;step_key uuid;validator_id uuid;tool_id text;validator_config jsonb;ordinal int := 1;
begin
 select id into strict lesson_key from public.practice_lessons where slug=p_lesson;
 insert into public.practice_steps(lesson_id,slug,sort_order,title_en,title_sr,instructions_en,instructions_sr,theory_en,theory_sr,target_object_ids,reference_modes,example_config,required)
 values(lesson_key,p_slug,10,p_title_en,p_title_sr,p_instructions_en,p_instructions_sr,p_theory_en,p_theory_sr,p_targets,array['off','outline','transparent','full'],jsonb_build_object('label_en','Synthetic implant exercise reference','label_sr','Sintetička referenca implantološke vežbe','mode','outline'),true)
 on conflict(lesson_id,slug) do update set sort_order=excluded.sort_order,title_en=excluded.title_en,title_sr=excluded.title_sr,instructions_en=excluded.instructions_en,instructions_sr=excluded.instructions_sr,theory_en=excluded.theory_en,theory_sr=excluded.theory_sr,target_object_ids=excluded.target_object_ids,reference_modes=excluded.reference_modes,example_config=excluded.example_config,required=true returning id into step_key;
 delete from public.practice_step_tools where step_id=step_key;
 delete from public.practice_step_validations where step_id=step_key;
 delete from public.practice_hints where step_id=step_key;
 foreach tool_id in array p_tools loop insert into public.practice_step_tools(step_id,tool_id) values(step_key,tool_id) on conflict do nothing; end loop;
 insert into public.practice_hints(step_id,slug,sort_order,title_en,title_sr,body_en,body_sr) values(step_key,'review-reference',10,'Review the exercise reference','Pregledajte referencu vežbe','Use only the supplied synthetic objects. Numeric values are targets for this exercise.','Koristite samo dostavljene sintetičke objekte. Numeričke vrednosti su ciljevi ove vežbe.');
 foreach validator_config in array p_validators loop
  insert into public.validation_configs(slug,validator_type,config,status) values('phase22_'||p_lesson||'_'||p_slug||'_'||ordinal,'custom'::public.validator_type,validator_config,'published') on conflict(slug) do update set validator_type='custom'::public.validator_type,config=excluded.config,status='published' returning id into validator_id;
  insert into public.practice_step_validations(step_id,validation_config_id,sort_order) values(step_key,validator_id,ordinal*10);
  ordinal := ordinal + 1;
 end loop;
end $$;

select pg_temp.seed_phase22_step('scan_body_matching','match_scan_body','Inspect Scan Body Matching','Pregledajte uparivanje scan body-ja','Select the synthetic scan body and fixture in Scene. Use Match scan body to align their shared reference positions.','Izaberite sintetički scan body i implantat u panelu Scene. Koristite Match scan body da poravnate njihove referentne položaje.','The scan body is a synthetic teaching object explicitly linked to a fixture ID. Matching here is a transform exercise, not scan interpretation.','Scan body je sintetički edukativni objekat izričito povezan sa ID-jem implantata. Uparivanje je vežba transformacije, a ne tumačenje snimka.',array['select','move','scene','camera'],array['implant-training-fixture-primary','implant-synthetic-scan-body'],array['{"type":"implant_check","check":"relationships"}'::jsonb]);
select pg_temp.seed_phase22_step('implant_visualization','identify_fixture_axis','Inspect Fixture and Implant Axis','Pregledajte implantat i osu implantata','Choose a synthetic training fixture. Read its library dimensions and the orange axis marker in the viewport.','Izaberite sintetički vežbovni implantat. Očitajte dimenzije biblioteke i narandžastu oznaku ose u prikazu.','The axis is calculated from the fixture transform; it is available to analysis and Design Check. The reference fixture is read-only.','Osa se izračunava iz transformacije implantata i dostupna je analizi i Design Check-u. Referentni implantat je samo za čitanje.',array['select','move','rotate','scene','camera'],array['implant-training-fixture-primary','implant-training-fixture-reference'],array['{"type":"implant_check","check":"fixture"}'::jsonb]);
select pg_temp.seed_phase22_step('position_and_depth','set_exercise_depth','Set Exercise Depth','Podesite dubinu vežbe','Set fixture depth to 8 mm using the Implant panel. Depth is measured from the top plane of the synthetic site block.','Podesite dubinu implantata na 8 mm u Implant panelu. Dubina se meri od gornje ravni sintetičkog bloka mesta.','8 mm is a target for this exercise only. The synthetic site reference does not represent patient anatomy.','8 mm je cilj samo ove vežbe. Sintetička referenca mesta ne predstavlja anatomiju pacijenta.',array['select','move','scene'],array['implant-training-fixture-primary'],array['{"type":"implant_check","check":"depth","targetMm":8,"tolerance":0.5}'::jsonb]);
select pg_temp.seed_phase22_step('angulation_and_axis','compare_axes','Compare Implant and Restorative Axes','Uporedite osu implantata i restauracije','Inspect the angle shown in degrees. Rotate the fixture to bring the axis difference within 12 degrees for this exercise.','Pregledajte ugao prikazan u stepenima. Rotirajte implantat tako da razlika osa bude unutar 12 stepeni za ovu vežbu.','The reference value is a target for this exercise and is not a clinical recommendation.','Referentna vrednost je cilj ove vežbe, a ne klinička preporuka.',array['select','rotate','camera'],array['implant-training-fixture-primary'],array['{"type":"implant_check","check":"axis","targetMm":12}'::jsonb]);
select pg_temp.seed_phase22_step('custom_abutment_and_emergence','review_abutment_emergence','Review Abutment and Emergence References','Pregledajte abatment i profil izranjanja','Adjust Custom abutment width and Emergence profile controls, then inspect both stable objects and their fixture relationship.','Podesite kontrole Custom abutment width i Emergence profile, pa pregledajte stabilne objekte i njihovu vezu sa implantatom.','These controls scale simplified educational reference meshes. They do not validate biological emergence or a clinical abutment design.','Ove kontrole menjaju razmeru pojednostavljenih edukativnih referentnih mreža. Ne potvrđuju biološki profil izranjanja niti klinički dizajn abatmenta.',array['select','move','rotate','scene'],array['implant-training-fixture-primary','implant-training-abutment','implant-training-emergence-reference'],array['{"type":"implant_check","check":"relationships"}'::jsonb]);
select pg_temp.seed_phase22_step('screw_channel_and_crown','inspect_screw_channel_crown','Inspect Screw Channel and Shared Crown','Pregledajte screw channel i zajedničku krunicu','Select the screw-channel axis reference and the synthetic crown. Confirm the crown links to the typed abutment object.','Izaberite referencu ose screw channel-a i sintetičku krunicu. Potvrdite da je krunica povezana sa tipizovanim objektom abatmenta.','The screw-channel marker is visual reference geometry. The crown uses the existing shared synthetic restorative tooth geometry.','Oznaka screw channel-a je vizuelna referentna geometrija. Krunica koristi postojeću zajedničku sintetičku restorativnu geometriju zuba.',array['select','scene','camera'],array['implant-training-abutment','implant-training-restoration','implant-training-screw-channel-reference'],array['{"type":"implant_check","check":"relationships"}'::jsonb]);
select pg_temp.seed_phase22_step('implant_review_capstone','review_implant_case','Run Implant Exercise Review','Pokrenite pregled implantološke vežbe','Inspect the section and measure tools. Run shared Proximity analysis between the training fixture and synthetic reference region, then run Design Check.','Pregledajte alate Section i Measure. Pokrenite zajedničku analizu blizine između vežbovnog implantata i sintetičke referentne regije, zatim Design Check.','The separation target is an exercise target only. Intersection, proximity and manually measured distance are different results.','Cilj rastojanja važi samo za vežbu. Presek, blizina i ručno izmereno rastojanje predstavljaju različite rezultate.',array['select','move','rotate','analysis','camera','scene'],array['implant-training-fixture-primary','implant-synthetic-reference-region'],array['{"type":"implant_check","check":"fixture"}'::jsonb,'{"type":"implant_check","check":"depth","targetMm":8,"tolerance":0.5}'::jsonb,'{"type":"implant_check","check":"axis","targetMm":12}'::jsonb,'{"type":"implant_check","check":"distance","targetMm":2}'::jsonb,'{"type":"implant_check","check":"relationships"}'::jsonb]);

insert into public.scenarios(domain_id,slug,difficulty,title_en,title_sr,description_en,description_sr,patient_code,indication_en,indication_sr,tooth_numbers,requirements_en,requirements_sr,additional_metadata,random_eligible,status,published_at)
select d.id,'synthetic_implant_training_case','advanced','Implant practice · synthetic site','Implantološka vežba · sintetičko mesto','Explore fixture, scan body, abutment and crown relationships in a synthetic educational case.','Istražite odnose implantata, scan body-ja, abatmenta i krunice u sintetičkom edukativnom slučaju.','PT-EDU-22','Synthetic implant restoration exercise','Sintetička vežba implantološke nadoknade',array[36]::smallint[],array['Inspect scan body matching','Adjust fixture depth and angulation','Compare implant and restorative axes','Review the synthetic reference geometry','Inspect the linked abutment and shared crown'],array['Pregledajte uparivanje scan body-ja','Podesite dubinu i angulaciju implantata','Uporedite osu implantata i restaurativnu osu','Pregledajte sintetičku referentnu geometriju','Pregledajte povezani abatment i zajedničku krunicu'],jsonb_build_object('caseInitializer','implant','geometryProvenance','internal-synthetic-educational','noPatientData',true,'materialPreset','synthetic-implant-education','material',jsonb_build_object('en','Synthetic educational geometry','sr','Sintetička edukativna geometrija'),'supplied',jsonb_build_object('en',jsonb_build_array('Synthetic site reference','Training implant fixture','Synthetic scan body','Synthetic abutment','Shared crown geometry'),'sr',jsonb_build_array('Sintetička referenca mesta','Vežbovni implantat','Sintetički scan body','Sintetički abatment','Zajednička geometrija krunice')),'notes',jsonb_build_object('en','Internally generated synthetic educational geometry only. No real patient data. Not for diagnosis, surgery or manufacturing approval.','sr','Samo interno generisana sintetička edukativna geometrija. Nema stvarnih podataka pacijenta. Nije namenjena dijagnostici, hirurgiji niti odobrenju izrade.')),true,'published',now()
from public.content_domains d where d.slug='implant'
on conflict(slug) do update set difficulty=excluded.difficulty,title_en=excluded.title_en,title_sr=excluded.title_sr,description_en=excluded.description_en,description_sr=excluded.description_sr,patient_code=excluded.patient_code,indication_en=excluded.indication_en,indication_sr=excluded.indication_sr,tooth_numbers=excluded.tooth_numbers,requirements_en=excluded.requirements_en,requirements_sr=excluded.requirements_sr,additional_metadata=excluded.additional_metadata,random_eligible=true,status='published',published_at=coalesce(public.scenarios.published_at,now());

insert into public.tool_object_roles(tool_id,object_role)
select 'scene',role from (values('implant'::public.cad_object_role),('abutment'::public.cad_object_role),('crown'::public.cad_object_role),('reference'::public.cad_object_role),('scan'::public.cad_object_role)) roles(role)
on conflict do nothing;
